"""Explain slab allocation, preservation exceptions and large allocation lengths."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1801': ('같은 크기의 빈 상자를 모아 다시 쓰는 창고를 생각해 보세요. 상자를 빌려줄 때 내용이 준비됐는지 검사표도 맞춰 줘야 해요.', 'slab 객체의 크기와 ZERO 요청에 따른 검사 상태를 이해합니다.', '32바이트 객체를 그리고 ZERO 있음은 준비됨, 없음은 미준비 검사표로 나누세요. 예외 조건은 없다고 가정하세요.', ['slab은 같은 종류의 작은 객체를 효율적으로 할당하고 재사용하는 방식이에요. 여기의 cache는 그런 객체들을 관리하는 묶음이며 CPU의 하드웨어 캐시와는 다른 뜻이에요. object는 할당 결과의 주소예요.', 'kmsan_slab_alloc은 실제 할당에 맞춰 KMSAN 검사 정보를 바꾸는 hook이에요. hook은 특정 일이 일어날 때 연결해서 부르는 함수예요. object가 NULL이면 할당 결과가 없으므로 먼저 돌아가요.', 'KMSAN이 꺼졌거나 도구 자신의 처리 중이어도 돌아가요. 생성 함수 ctor가 있거나 SLAB_TYPESAFE_BY_RCU 표시가 있는 cache도 별도 예외로 돌아가요. 따라서 아래 ZERO 분기는 이 조건들을 통과한 객체에만 적용돼요.', 'flags에 __GFP_ZERO가 있으면 unpoison으로 준비됨을 표시해요. 0으로 채우는 할당 요청에 검사표를 맞추는 것이에요. 실제 데이터에 0을 쓰는 할당자 작업과 이 함수의 검사표 변경은 따로 이루어져요.', 'ZERO 표시가 없으면 poison으로 미준비 상태를 표시해요. 어느 쪽이든 범위는 s->object_size예요. object_size가 32면 32바이트의 검사 상태를 바꾸며 무조건 한 페이지 전체를 바꾸지 않아요.', '두 경로는 enter_runtime과 leave_runtime 사이에서 실행해요. 미준비 표시를 없애는 unpoison과 미준비 표시를 넣는 poison은 반대 방향이에요. 이름만 외우기보다 준비 상태가 어느 쪽으로 바뀌는지 화살표로 그리세요.'], [('예외 조건을 통과한 slab 할당에 ZERO 표시가 있으면 검사표를 어떻게 바꾸나요?', ['반드시 미준비 poison을 새로 넣어요', 'unpoison으로 준비됨을 표시해요'], '정답은 두 번째예요. 0으로 채운 할당의 상태에 검사 정보를 맞추는 경로예요. 이 검사 함수가 실제 객체 내용을 0으로 채운다고 혼동하지 마세요.'), ('이 hook가 바꾸는 범위의 길이는 어디서 얻나요?', ['cache의 object_size에서 얻어요', '항상 PAGE_SIZE 하나로 정해요'], '정답은 첫 번째예요. 두 내부 호출 모두 s->object_size를 전달해요. 32바이트 객체의 예라면 길이도 32예요.')]), 'os1802': ('다시 쓸 물건의 상태를 보존해야 하는 경우에는 매번 검사표를 새것처럼 바꾸면 안 돼요. 일반 물건과 특별한 보관 규칙을 나눠 봐요.', 'constructor·RCU 조건이 ZERO 검사보다 먼저인 이유를 이해합니다.', 'ctor 있음, RCU 표시 있음, 둘 다 없음의 세 줄에 조기 반환 또는 ZERO 검사 진행을 적으세요.', ['ctor는 constructor의 줄임말로 객체를 준비하는 생성 함수예요. slab cache에 이 함수가 있으면 객체를 준비하고 재사용하는 별도 규칙을 고려해야 해요. 이 hook가 호출될 때마다 ctor를 직접 실행하는 코드는 없어요.', 'RCU는 여러 실행 흐름이 자료를 읽는 동안 제거·회수 시점을 조정하는 기법이에요. 여기서는 SLAB_TYPESAFE_BY_RCU라는 cache 표시가 있는지만 확인해요. 이 표시 하나를 검사하는 것과 전체 RCU 알고리즘을 실행하는 것은 달라요.', '원문 조건은 s->ctor || (s->flags & SLAB_TYPESAFE_BY_RCU)예요. ||는 둘 중 하나라도 참이면 참이라는 뜻이에요. &는 flags 안에 특정 표시 비트가 켜졌는지 살피는 데 쓰여요.', '둘 중 하나에 해당하면 runtime 진입 전에 돌아가요. 그 뒤에 있는 ZERO 검사와 poison·unpoison은 실행하지 않아요. ZERO 요청이 있어도 앞의 예외 조건이 먼저라는 순서를 기억하세요.', '주석은 이런 경우 이전 사용 뒤의 메모리 상태가 바뀌지 않았기 때문에 아무것도 하지 않는다고 설명해요. 이 hook가 검사 상태를 일괄적으로 새로 표시하지 않고 보존하는 정책이에요. 보존을 모든 객체의 영구적인 안전 보장으로 받아들이면 안 돼요.', '종이에 표시 비트를 켜고 끄며 어느 줄에서 돌아가는지 연습할 수 있어요. 그 연습은 생성 함수 실행, 여러 CPU의 동시 접근, RCU 대기 기간의 정확성까지 검증한 것은 아니에요. 이번 수업에서는 이 짧은 분기가 결정하는 범위를 구별하세요.'], [('ctor가 있는 cache에서 할당 hook는 새 poison을 추가하나요?', ['네. 모든 할당에 무조건 추가해요', '아니요. 앞 조건에서 돌아가 갱신을 생략해요'], '정답은 두 번째예요. ctor 조건은 runtime 진입과 ZERO 분기보다 앞에 있어요. 뒤에서 무슨 처리를 하는지 보기 전에 return을 먼저 따라가세요.'), ('RCU 표시를 켠 모델에서 조기 반환을 확인하면 전체 RCU 대기 알고리즘도 검증한 것인가요?', ['아니요. 이 hook의 조건 분기를 확인한 것이에요', '네. 모든 동시 접근과 객체 수명이 검증돼요'], '정답은 첫 번째예요. 비트를 보고 돌아가는 코드와 실제 독자들의 접근이 끝날 때까지 기다리는 처리는 서로 다른 검증 대상이에요.')]), 'os1803': ('반납한 물건을 계속 쓰면 문제가 생길 수 있어요. 검사 도구는 일반 객체에 반납 표시를 남기지만, 상태를 보존하는 특별한 경우도 따로 다뤄요.', '일반 slab 해제 표시와 constructor·RCU 예외를 구별합니다.', '일반 객체는 CHECK와 FREE를 함께, 특별한 cache는 조기 반환으로 표시하세요.', ['kmsan_slab_free는 slab 객체를 해제하는 과정의 검사 hook이에요. 해제는 사용하던 객체를 반납하는 일이에요. 이 hook는 객체를 직접 할당자에 돌려주는 전체 과정 대신 검사 정보를 처리해요.', '먼저 검사가 꺼졌거나 도구 자신의 처리 중이면 돌아가요. 이어 SLAB_TYPESAFE_BY_RCU cache인지, ctor가 있는지 확인해요. 이 두 경우도 일반 poison 경로에 들어가지 않아요.', 'RCU cache에는 읽는 쪽과 객체 수명에 관한 특별한 규칙이 있어요. 원문은 관련 기간의 사용 때문에 이 표시를 생략한다고 설명해요. 그렇다고 모든 해제 객체를 아무 때나 읽어도 된다는 뜻은 아니에요. 실제 수명 조건은 별도예요.', 'ctor가 있으면 다음 할당까지 객체 상태를 유지해야 한다는 주석이 있어요. 이 hook는 그 상태를 보존하기 위해 돌아가요. 이 방식의 해제 후 사용 탐지가 제한된다는 뜻이지 해제 후 사용 오류가 불가능하다는 뜻은 아니에요.', '일반 경로는 runtime에 들어가 object_size 길이에 poison을 요청해요. 옵션은 KMSAN_POISON_CHECK | KMSAN_POISON_FREE예요. CHECK는 검사 정보 범위 진단에, FREE는 해제와 관련된 원인 표시에 연결돼요. |는 두 옵션을 함께 켜는 비트 연산이에요.', '메모리 요청 조건으로 GFP_KERNEL도 전달하고, 호출 뒤 runtime에서 나와요. poison은 shadow의 미준비 표시와 원인을 갱신하는 것이에요. 실제 데이터 바이트를 지우는 동작이라고 생각하면 안 돼요.'], [('일반 slab free 경로가 전달하는 poison 옵션은 무엇인가요?', ['NOCHECK 하나만 전달해요', 'CHECK와 FREE를 함께 전달해요'], '정답은 두 번째예요. 원문은 CHECK | FREE예요. 범위 진단과 해제 원인 표시는 별개의 옵션으로 함께 전달돼요.'), ('ctor가 있는 cache에서 해제 표시 갱신을 생략하는 이유는 무엇인가요?', ['다음 할당까지 객체 상태를 보존하는 규칙 때문이에요', '한 번 해제한 객체가 영원히 안전하기 때문이에요'], '정답은 첫 번째예요. 상태 보존 때문에 이 hook의 탐지를 생략하는 것이에요. 탐지가 없다는 사실을 안전성 증명으로 바꾸어 읽지 마세요.')]), 'os1804': ('큰 상자를 받았어도 이번에 요청한 부분의 길이는 따로 적혀 있어요. 검사 함수가 그 요청 길이를 쓰는지, 상자 전체 크기를 쓰는지 확인해요.', '큰 kmalloc 할당의 요청 size와 실제 확보 공간을 구별합니다.', '요청 size와 실제 확보 공간을 두 칸에 쓰고 이 hook의 길이 화살표는 size로 연결하세요.', ['kmsan_kmalloc_large는 큰 kmalloc 할당의 검사 정보를 처리하는 hook이에요. kmalloc은 커널에서 메모리를 요청하는 기능이에요. ptr는 받은 주소, size는 요청 길이, flags는 요청 조건 표시예요.', 'ptr가 NULL이면 먼저 돌아가요. NULL은 여기서 사용할 할당 결과가 없다는 뜻이에요. unlikely는 그 조건이 드물 것으로 예상한다는 표시이며, 참인 조건을 무시하라는 명령이 아니에요.', '검사가 꺼졌거나 도구 자신의 처리 중이어도 돌아가요. 정상 경로에서는 runtime에 들어가 ZERO 표시가 있는지 보고, 있으면 checked true로 unpoison을 요청해요. 이는 준비된 상태를 검사표에 반영하는 작업이에요.', 'ZERO가 없으면 전달받은 flags와 KMSAN_POISON_CHECK를 사용해 poison을 요청해요. 아직 값을 준비하지 않은 상태를 표시하는 방향이에요. 두 경로 모두 마지막에 runtime에서 나와요.', '이 함수는 두 경로의 길이에 size를 그대로 전달해요. slab 함수가 cache의 object_size를 썼던 것과 달라요. 실제 확보한 페이지 전체 크기를 여기서 page_size로 새로 계산하지 않아요.', '예를 들어 요청 길이가 9000바이트이고 할당자가 확보한 공간이 그보다 크더라도, 이 hook의 검사 요청 길이는 9000이에요. 큰 할당의 실제 확보 크기는 할당 규칙에 따라 달라지므로 여기서 확정하지 않아요. 뒤의 해제 hook가 쓰는 길이와도 따로 비교해야 해요.'], [('큰 kmalloc 할당 hook가 검사 정보 함수에 넘기는 길이는 무엇인가요?', ['항상 확보된 페이지 전체 크기예요', '인자로 받은 요청 size예요'], '정답은 두 번째예요. poison과 unpoison 양쪽 모두 size를 그대로 사용해요. 실제 확보 공간이 더 크다고 이 함수가 그 전체를 자동 선택하지 않아요.'), ('ptr가 NULL이면 내부 poison을 호출하나요?', ['아니요. 첫 조건에서 돌아가요', '네. 실패한 주소도 정상 객체처럼 처리해요'], '정답은 첫 번째예요. unlikely(ptr == NULL)이 참이면 return해요. 드문 조건이라는 표시는 실패 검사를 없애지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_446.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
